import 'package:cloud_firestore/cloud_firestore.dart';
class ReflectionService{final FirebaseFirestore db;ReflectionService({FirebaseFirestore? firestore}):db=firestore??FirebaseFirestore.instance;Future<void> save(String u,String wins,String learnings,String next)async{await db.collection('users').doc(u).collection('reflections').add({'wins':wins.trim(),'learnings':learnings.trim(),'next':next.trim(),'createdAt':FieldValue.serverTimestamp()});}Stream<QuerySnapshot<Map<String,dynamic>>> watch(String u)=>db.collection('users').doc(u).collection('reflections').orderBy('createdAt',descending:true).limit(30).snapshots();}